INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Desktop Explorer', 'Desktop Explorer is an exploration-puzzle game set in a retro-style operating system. Solve puzzles by interacting with built-in software features, immersing yourself into a realistic late 90’s computer experience. The game follows a fairly innocent narrative as you progress through it’s puzzles. However it becomes clear to you that there is more than meets the eye with this machine, as you slowly see its familiar façade fade away in favor of a darker aesthetic..' FROM games WHERE igdb_id = 275251 ON CONFLICT (game_id, language_code) DO NOTHING;
