INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Project ReMind', '"Welcome to the end. My end" Manipulate machinery, open secret passages and bypass computers to remember your life, from your first discovery to your own death bed. In this first-person narrative puzzle game investigate a mysterious presence looking for the answer that haunted you since THAT day.' FROM games WHERE igdb_id = 362052 ON CONFLICT (game_id, language_code) DO NOTHING;
