INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tuoni', 'A turn-based roguelite RPG set in a mythic northern wilderness. Explore procedurally generated lands, battle eerie folkloric creatures, and craft powerful builds on your journey to the land of the dead. Experiment with diverse playstyles in a richly tactical, old-school inspired adventure.' FROM games WHERE igdb_id = 350158 ON CONFLICT (game_id, language_code) DO NOTHING;
