INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Neopets: Mega Mini Games Collection - The Neopian Arcade Odyssey', 'Neopets: The Mega Mini Games Collection is a lovingly remastered collection of 26 fan-favourite mini-games from the golden age of Neopets! From collecting Doughnutfruits in Hasee Bounce, launching Kass in Kass Basher, or chasing Neggs in Meerca Chase, the magic of Neopets is back! And introducing an all-new adventure: Starlight Symphony, starring Nyx in a dazzling musical quest through the stars!' FROM games WHERE igdb_id = 386211 ON CONFLICT (game_id, language_code) DO NOTHING;
