INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aurora Polaris', 'Aurora Polaris is a vertical shoot ''em up set in a post-pandemic future where a mysterious old engineer brings together four unlikely pilots to stop a technocratic regime known as NOX. Blending arcade action, anime-inspired visuals, and heartfelt narrative, players engage in intense boss fights, upgrade their ships, and explore handcrafted stages across a frozen Earth. Featuring local co-op, emotional cutscenes, and a unique sci-fi take on holiday mythology.' FROM games WHERE igdb_id = 341690 ON CONFLICT (game_id, language_code) DO NOTHING;
