INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('direction-quad', 385117, '2026-01-13', 76, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobtun.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5lmp.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Direction Quad', 'Direction Quad is a 2D action-adventure presented in top-down pixel art style. Take the role of young Quad as he hops through the swamp in any diagonal direction, collecting coins and bugs along the way. The objective is to get Quad from his starting lily pad to the finish line of each stage without colliding with the terrain or any treacherous traps. As you advance, the mazelike levels get more complex! Use bumpers to ricochet along the best lines, hit switches to open new paths and keep Quad from kicking the bucket! Replay stages as many times as it takes, but beware, there is greater danger lurking in the swamp than even the Wize Toad may realize!' FROM games WHERE igdb_id = 385117 ON CONFLICT (game_id, language_code) DO NOTHING;
