INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Owlet''s Embrace', 'An owlet afraid of flight sets off to explore a vibrant mysterious world and rediscover itself. On this heartwarming adventure, you''ll confront the owlet''s deepest fears as only the greatest challenges can lead to the most profound growth. Owlet''s Embrace is an action exploration platformer, blending fast paced grappling hook manouvers with combat and emotional discovery.' FROM games WHERE igdb_id = 272485 ON CONFLICT (game_id, language_code) DO NOTHING;
