INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Contact Protocol', 'Contact Protocol is a starship job simulator taking place in a gritty, cassette-future. Humanity has spread throughout the solar system and started extracting its natural resources. You play as the security officer aboard PALE HORSE - a Galileo Corporation vessel carrying miners set for Ganymede, Jupiter''s biggest moon. It’s your job to assess the intentions of approaching ships, decide their fate, and keep your crew alive. The company is watching.' FROM games WHERE igdb_id = 373878 ON CONFLICT (game_id, language_code) DO NOTHING;
