INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Forza Horizon 6', 'Discover the breathtaking landscapes of Japan in over 550 real-world cars and become a racing Legend at the Horizon Festival. Start your journey as a tourist and explore a world full of hit music and Japanese culture. Build a Valley Estate, acquire awe-inspiring homes, and display your prized car collection in fully Customizable Garages. Cruise the roads with your friends and join Car Meets around Japan, unleash your imagination with EventLab and build together in Horizon CoLab.' FROM games WHERE igdb_id = 348330 ON CONFLICT (game_id, language_code) DO NOTHING;
