INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Active Matter', 'You’re an operative stuck in a time loop, always brought back from the dead to the same point. Choose your loadout and enter quantum unstable zones rich with active matter — a substance capable of warping and ripping the very fabric of space and time. Fight against rivals from other timelines, survive physics-breaking anomalies and try to stay alive. Harvest active matter, gather loot and extract to a safe place before the whole zone ceases to exist with everything inside it.' FROM games WHERE igdb_id = 322158 ON CONFLICT (game_id, language_code) DO NOTHING;
