INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Timberborn', 'Humans are long gone. In a world struck by droughts and toxic waste, will your lumberpunk beavers do any better? Timberborn is a sandbox city-building game featuring ingenious animals, vertical architecture, water physics, and terraforming. Contains high amounts of wood.' FROM games WHERE igdb_id = 126381 ON CONFLICT (game_id, language_code) DO NOTHING;
