INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Way of Wrath', 'The Way of Wrath is a story-driven turn-based tactical RPG set in an ancient world governed by shamanistic laws. You explore the beautifully handcrafted landscape, rebuild defences of an old fort, take on quests and unite war torn people against the imminent wrath of enemy forces. Will you lead with an iron fist, diplomacy or trickery is up to you, but with every choice you make be prepared to face the consequences.' FROM games WHERE igdb_id = 117329 ON CONFLICT (game_id, language_code) DO NOTHING;
