INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Unsealed: The Mare', 'Unsealed: The Mare is a first-person psychological horror game set in a nightmare rooted in memory and trauma. Players explore dark, oppressive environments while uncovering fragmented messages and hidden memories that subtly alter the world around them. The experience emphasizes tension, sound awareness, and atmosphere, encouraging players to move carefully, listen closely, and piece together meaning through environmental storytelling.' FROM games WHERE igdb_id = 384922 ON CONFLICT (game_id, language_code) DO NOTHING;
