INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'City Hunter', 'Released on March 2, 1990 as the only official home-console game of its kind, this legendary title returns 35 years later—now launching worldwide simultaneously with all the excitement of its original debut. This game is more than just a remake—it’s a fusion of nostalgia and newness. With multi-language localization, both long-time fans and new players can enjoy the experience without a language barrier. Relive the excitement and emotional moments once more.' FROM games WHERE igdb_id = 370192 ON CONFLICT (game_id, language_code) DO NOTHING;
