INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sondro Gomez: A Sunova Story', '"Sondro Gomez: A Sunova Story" is an action-adventure platformer following the story of a failing musician named Sondro, who must seek and recover the wish-granting Mystic Orbs to repay his debt to the mysterious Masked Man. Can he find them before the many rogues of Sunova beat him to the punch?' FROM games WHERE igdb_id = 170662 ON CONFLICT (game_id, language_code) DO NOTHING;
