INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Latitude 76: Land of the Onkilons', 'Latitude 76: Land of the Onkilons is an action-adventure game inspired by the true story of the 1900-1902 polar expedition. It tells the story of brave explorers who decide to prove the legend of the phantom island in the Arctic Ocean. Switch between characters, use your grappling hook to explore a phantom island, home to mammoths. Face threats from hunters and choose to play stealthily or confront the dangers head-on. Inspired by real events.' FROM games WHERE igdb_id = 352428 ON CONFLICT (game_id, language_code) DO NOTHING;
