INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mixtape', 'On their last night of high school, three friends embark on one more adventure together. Play through a mixtape of memories, set to the soundtrack of a generation. En route to their final party together, a perfectly-curated playlist draws them into dreamlike reenactments of their formative memories. Experience a variety of narrative vignettes exploring the pivotal moments that shaped them. It''s the greatest hits of teenage friendship, from the first kiss to the last dance.' FROM games WHERE igdb_id = 305157 ON CONFLICT (game_id, language_code) DO NOTHING;
