INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Navinosuke: The Yo-kai Buster', 'A long-lost 2D pixel art RPG returns across time. Originally completed two decades ago but never released, this hidden gem is now being faithfully rebuilt by KOHACHI STUDIO for Nintendo Switch. Set in ancient Japan, you play as Navinosuke, a young onmyoji-in-training, meeting and battling over 150 unique yokai. Plan your tactics using turn-based auto battles and a shikigami system, and explore a whimsical, strategy-driven Japanese fantasy world.' FROM games WHERE igdb_id = 349430 ON CONFLICT (game_id, language_code) DO NOTHING;
