INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ExoMecha', 'ExoMecha is a brand new free-to-play online competitive first-person shooter that takes place in Omecha, a new and untouched planet with exotic environments. ExoMecha offers you breathtaking gaming experience with its flexible playing style, mechs, unique gadgets and abilities, and boss battles. ​ExoMecha is an immersive experience with team-based large scale battles, a unique battle royale game mode, and an objective-based game mode.' FROM games WHERE igdb_id = 135987 ON CONFLICT (game_id, language_code) DO NOTHING;
