INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mina the Hollower', 'Mina the Hollower is a bone-chilling action-adventure game featuring classic gameplay and an 8-bit aesthetic in the style of Game Boy Color, refined for the modern era. Quick and deliberate 60fps action combat, captivating world design, and top-down adventuring combine in a nostalgic blend. Whip foes, burrow through the ground, and explore a pixel-perfect world in Mina the Hollower, a brand new game from the developers who brought you Shovel Knight!' FROM games WHERE igdb_id = 189781 ON CONFLICT (game_id, language_code) DO NOTHING;
