INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Five Nights at Freddy''s: Blood & Gears', '"You hoped you''d never have to return to this place of sorrow, but after 20 years, something has called you back." Five Nights at Freddy''s: Blood & Gears is a complete reimagining of Scott Cawthon''s original *Five Nights at Freddy''s* game. The game is directed by JDBRYANT and is created by a passionate team of over 30 people.' FROM games WHERE igdb_id = 331177 ON CONFLICT (game_id, language_code) DO NOTHING;
