INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marathon', 'A PvP-focused extraction shooter set on the mysterious planet of Tau Ceti IV, Marathon will see players inhabit the bodies of Runners, cybernetic mercenaries who have been designed to survive the planet’s harsh environments and explore the lost colony that once inhabited Tau Ceti’s surface. Players will engage solo or in crews of three, searching for mysterious alien artifacts, as well as for valuable loot and new weapons and gear that they can add to their collection.' FROM games WHERE igdb_id = 250630 ON CONFLICT (game_id, language_code) DO NOTHING;
