INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('redemption-of-the-damned', 147345, '2026-06-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co30a5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/argn1.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Redemption of the Damned', 'You are a field doctor''s assistant who was heading to a distant village to help local peasants. Someone attacked your stagecoach and you wake up in a mass grave, being the only survivor. The player fights against monsters and other evil spirits in various biomes of the cursed forest, and the only safe place is the village, where he can complete tasks, recuperate or replenish supplies. In each location the player will meet with the guardian of this zone - the boss, who is the iconic character of the folklore of Western and Eastern Europe. The main goal of the game is to get into the high castle in order to eliminate its owner. The player''s arsenal is represented by a wide range of firearms typical for the chosen era - ancient flintlock pistols, classic revolvers, muskets and rifles, as well as special tools for certain types of enemies like vampires, ghouls, werewolves, swamp creatures, spirits, etc. What scared you, being myths and scary tales, becomes reality and...attacks!' FROM games WHERE igdb_id = 147345 ON CONFLICT (game_id, language_code) DO NOTHING;
