INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gamblers-table', 342853, '2026-01-11', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9s0k.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3ksv.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gamblers Table', 'Gamblers Table is an idle automation game where you toss coins to earn money. Buy bigger and better coins, unlock upgrades and hire little helpers to automate the process and take care of all the busy flipping work for you. Simple. Satisfying. Click a coin to toss it. Every time it lands on Heads, you earn money. The more coins you own, the more you can flip. Buy upgrades to make them flip faster and yield more money. Discover curious interactions and unexpected synergies between different coin types. Hire little helpers to take care of all the manual labour for you. They don’t complain, and they never question. Leave your fortune behind and rise to something greater. Start again with peculiar new talents you didn’t have before. Admire your riches, lean back, and watch your automated coin-flipping empire grow.' FROM games WHERE igdb_id = 342853 ON CONFLICT (game_id, language_code) DO NOTHING;
