INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Scavland', 'Scavland is a hardcore, top-down pixel art survival game set in a Post-Apocalyptic Soviet Era. Explore a world ravaged by war and the deadly Mist, scavenging for resources, taking risky jobs, and seeking refuge in harsh settlements. The wasteland is relentless—everything is out to kill you.' FROM games WHERE igdb_id = 339674 ON CONFLICT (game_id, language_code) DO NOTHING;
