INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tamashika', 329975, '2026-04-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaacw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar40uh.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tamashika', 'The game is about keeping your mind at one place. Patterns in sensate experience reinforce an illusion of continuity. The dream is a construction of the mind that perpetuates the illusion. The cartesian prison is a hall of mirrors, a recursive labyrinth. Each a reflection of me—only patterns and processes. The present moment is the only thing that is real—focus. Chaotic attractors are seizing your attention. Don’t push or pull at it. You have to reduce model complexity, you must cultivate flow. The game is about keeping your mind at one place! Concentrate… and remember… Attention is all you need.' FROM games WHERE igdb_id = 329975 ON CONFLICT (game_id, language_code) DO NOTHING;
