INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LEGO Batman: Legacy of the Dark Knight Deluxe Edition', 'Includes: • Full Base Game • Legacy Collection: - Over 30 launch-day items included across 3 Themed Packs: Arkham Trilogy Pack, Batman Beyond Pack, Party Music Pack - Each Themed Pack includes 7 suits (1 for each playable character), 1 Batmobile, and a set of 5 Batcave customization props - 3-day Advanced Access • Mayhem Collection*: - Includes new Story Mission and Mayhem Mode featuring The Joker and Harley Quinn, along with a villain-themed Sinister Pack - Break out of Arkham Asylum as playable characters The Joker and Harley Quinn in an all-new Story Mission - Cause chaos on the streets of Gotham City in the all-new Mayhem Mode - Sinister Pack includes 7 suits (1 for each of the original playable characters), 1 Batmobile, and 1 Batcave prop set' FROM games WHERE igdb_id = 387030 ON CONFLICT (game_id, language_code) DO NOTHING;
