INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marvel Tokon: Fighting Souls', 'Assemble your team of legendary Marvel characters in the ultimate 4v4 tag team fighter from PlayStation Studios, Arc System Works and Marvel Games. Immerse yourself in the Marvel universe like never before with an iconic roster of heroes and villains, authentic stages, and intuitive gameplay mechanics. Experience the thrill of fast-paced over the top action with stunning anime-inspired visuals, where every battle is a unique and exciting team VS battle experience.' FROM games WHERE igdb_id = 347132 ON CONFLICT (game_id, language_code) DO NOTHING;
