INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bendy-the-cage', 274714, '2026-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaryx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4l69.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bendy: The Cage', 'Test your sanity as you take control of Henry in this third person horror experience taking place during the events of Bendy and the Dark Revival. Condemned to the Keeper prison known as "The Pit", Henry must survive the horrific inmates and mangled experiments set loose to devour him. A labyrinth of steel industrial dread lay before him as his mind is invaded by the past. Discover the hidden blood-stained truth behind the monsters as you explore the dark levels of The Pit, slowly making your way to the very top of the facility. Take on the darkness with your axe in brutal melee combat: Unleash fast and heavy strikes, block and parry incoming attacks, shove foes away, stomp on enemies with a vengeance, and time dodges to avoid being torn apart by the things that hunt you. Dive into the shadows for limited supplies as you embark on a twisted tale of Henry''s self discovery while facing down new and familiar creatures of the ink. Find the maestro. Escape the prison. Fight the madness.' FROM games WHERE igdb_id = 274714 ON CONFLICT (game_id, language_code) DO NOTHING;
