INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('grand-containment-sector-4', 394943, '2026-03-13', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobrus.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc12lk4.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grand Containment Sector 4', 'Grand Containment : Sector 4, "They said it was just a server farm. They lied." For years, Grand Gaming Technologies Private Limited (GGTPL) has been a leader in virtual entertainment. But rumors have started to circulate on the dark web—rumors of people going missing near their remote "Logistics Center" hidden deep in the forest. They call it Sector 4. You are a whistleblower who has received a cryptic coordinate. Armed with only a flashlight and a camera, you must infiltrate the decaying industrial complex to find out what GGTPL is really building. But the factory isn''t abandoned. The machinery is still humming, the security protocols are active, and something horrifying is stalking the assembly lines. Investigate. Survive. Expose' FROM games WHERE igdb_id = 394943 ON CONFLICT (game_id, language_code) DO NOTHING;
