INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Adventures of Elliot: The Millennium Tales', 'The Adventure of Elliot: The Millennium Tales is an action RPG set in the world of Philabieldia - a beautiful but savage land dominated by warring beast tribes. Humanity’s last bastion is the Kingdom of Huther, protected by its tall walls and Princess Heuria’s powerful magic. When a mysterious set of ruins is discovered, a young adventurer named Elliot and his fairy companion Faie are sent off on a journey to investigate. What seems like a simple, if dangerous, mission soon becomes a grand saga that will be woven across time and space.' FROM games WHERE igdb_id = 358534 ON CONFLICT (game_id, language_code) DO NOTHING;
