INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hijack Jump', 'Hijack Jump is a tricky parkour game where your success depends on friends… or enemies. Every player can be hijacked by others. Hijackers don’t just watch – they can interfere with your run, blasting you with stuff to knock you down. There’s no limit to how many spectators can join and mess with your game.' FROM games WHERE igdb_id = 362920 ON CONFLICT (game_id, language_code) DO NOTHING;
