INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('romeo-is-a-dead-man', 347119, '2026-02-11', 84, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coakmt.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4139.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Romeo is a Dead Man', 'Latest ultra-violent sci-fi action title from Grasshopper Manufacture and Suda51. Step into the blood-soaked boots of Romeo Stargazer, a man pulled back from the brink of death by a time paradox gone wrong. Now reborn as Agent Dead Man of the FBI Space-Time Division, and armed with the mysterious Dead Gear mask, Romeo must chase the universe’s most dangerous fugitives across alternate realities. Blending high-octane gunplay, brutal sword combat, and over-the-top sci-fi insanity, Romeo Is a Dead Man is GhM’s bloodiest action game yet. Players can expect mind-bending twists, outrageous gimmicks, and a deeply cathartic combat system that turns enemies’ powers against them in universe-shattering battles. As Romeo tears through the multiverse, he’s also on a desperate quest to find Juliet, his mysteriously vanished girlfriend. With a narrative that fuses love, loss, and metaphysical chaos, Romeo Is a Dead Man offers a stylish and unpredictable journey through the very fabric of time itself. Can you survive the bleeding edge of space-time? Or will you become just another ghost in the paradox?' FROM games WHERE igdb_id = 347119 ON CONFLICT (game_id, language_code) DO NOTHING;
