INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Interdimensional Vending Machine', 'Inspired by SCP-261, you play as a homeless girl struggling to survive in a distorted city using a vending machine that should not exist. Every coin dispenses impossible food that defies biology and logic, and every meal reshapes your fate. How long can you survive before you stop being human?' FROM games WHERE igdb_id = 391514 ON CONFLICT (game_id, language_code) DO NOTHING;
