INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Papa Needs a Headshot', 'Papa Needs a Headshot is a brutal western-steampunk FPS soaked in kin blood. Rip through flesh and bend the battlefield with your cursed metal arm. Use every bullet wisely to slaughter freaks and abominations on your warpath. Keep enduring only to put a bullet in the skull of the man who made you.' FROM games WHERE igdb_id = 360095 ON CONFLICT (game_id, language_code) DO NOTHING;
