INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('disciples-domination', 360140, '2026-02-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa8ss.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3z7s.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disciples: Domination', 'Rule through the chaos! Fifteen years after Avyanna freed Nevendaar from the tyrannical grip of the gods, Disciples: Domination returns you to a realm hanging in the balance. In this dark fantasy strategy RPG with turn-based combat, take your place on Queen Avyanna’s throne – and attempt to hold together a crumbling kingdom. The fire of doubt burns scorching within her, sparked by the crushing weight of the throne in Yllian and stoked by twisted dreams of becoming one of the very monsters she once defied – and destroyed. Paralyzed by fear and haunted by her own power, Avyanna’s rule begins to crack. Allies disappear and abandon her. An unknown force spreads strife and madness through her realm. The choice is yours – shape the future, for salvation or ruin. As you chase the truths behind the ceaseless conflicts, dark magic and lurking conspiracies infecting your rotting empire, you’ll face betrayal, strife, and shadowy schemes. Uncover the long-lost Mountain Clans, witness the rise of an ancient cult and confront a corrupted seer whose visions have awoken bitter grudges, while old enemies are on the rise. It will take all your courage to save Nevendaar. Are you brave enough to face – and embrace – its darkest truths?' FROM games WHERE igdb_id = 360140 ON CONFLICT (game_id, language_code) DO NOTHING;
