INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Saveseeker', 'Saveseeker is a turn-based RPG adventure that follows a tenacious time-traveling girl who must save the world from her father. Play as Emmer Edette, a cheerful and carefree child who discovers she inherited her famous father''s ability to ''save'' moments in time at specific points worldwide. Alongside her grumpy dragon toy sidekick, Tippleton, she embarks on a journey to overwrite all of the world’s save points (“Save Stops”) and confront her father, a once-great Hero using his power for nefarious means. Explore six vibrant lands, recruit the Hero’s former foes, and save the world from an untimely end!' FROM games WHERE igdb_id = 356279 ON CONFLICT (game_id, language_code) DO NOTHING;
