INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sparkball', 'Sparkball is a 4v4 adrenaline-packed ‘sports brawler’ where players select from a cast of lovably unique heroes and carefully balance both ballin'' and brawlin'' to score in the enemy team''s goal! Affectionately described as League of Legends meets Rocket League (or Kung Fu-tbol!), Sparkball grips you immediately with its dopamine-inducing take on combat sports and keeps you coming back for more as you strive to master its surprisingly complex strategies.' FROM games WHERE igdb_id = 152427 ON CONFLICT (game_id, language_code) DO NOTHING;
