INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('zero-racers', 176043, '2026-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobdff.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar56fq.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zero Racers', 'Also known as G-Zero, Zero Racers would have been the first 3D entry in the F-Zero series. With the F-Zero Grand Prix over, racers now take part in the high-thrill, zero-gravity G-Zero Grand Prix races. The racers effectively fly around the 3D wireframe circuits. Three of the original racers were confirmed to return (Falcon, Stingray and Goose), and joined by a new craft, Origammy. A prototype of the game was shown at E3 1996, and it was previewed by Nintendo Power magazine. However, by 1996 the Virtual Boy was already considered a failure and was discontinued shortly after. The game was later announced for release through Virtual Boy Nintendo Classics.' FROM games WHERE igdb_id = 176043 ON CONFLICT (game_id, language_code) DO NOTHING;
