INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tearscape', 318752, '2026-02-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co99ts.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar360r.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tearscape', 'Discover a Gothic world in this 2D top-down action-adventure, blending fast-paced combat, exploration, and pixel art inspired by Game Boy Color classics. Fight monstrous foes, unlock new abilities, and explore a non-linear map filled with hidden secrets and dangerous challenges. Master precise combat, where every strike and dodge matters. Strategically manage your stamina by carefully considering each move as you face off against grotesque enemies. You have a limited number of healing flasks—use them wisely and plan your moments to recover carefully. Upgrade your character''s stats to remain effective and competitive in combat. Discover powerful items hidden in the dungeons that enhance both combat and exploration. Unlock new abilities to defeat enemies more effectively and access hidden paths, uncovering deeper secrets within the world. Uncover hidden dungeons throughout Tearscape''s dark, interconnected world. Each dungeon holds unique challenges, powerful items, and deadly enemies, pushing your combat and exploration skills to the limit. Face off against challenging bosses—massive, grotesque creatures born from dark experiments. Each encounter demands precise timing, strategy, and mastery of your abilities to emerge victorious. Explore the vast, interconnected map filled with branching paths, hidden shortcuts, and secret areas. The non-linear design encourages exploration, rewarding you with powerful items and new abilities. Encounter a diverse cast of NPCs, some offering guidance, others seeking your help, and a few with their own hidden agendas. Every interaction adds depth to the story.' FROM games WHERE igdb_id = 318752 ON CONFLICT (game_id, language_code) DO NOTHING;
