INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'After the Wane', 'Retracing the footsteps of a mother she never knew, Lena''s trying to make it as a dancer in the city. Caught in a quarrel between dance companies, dealing with love and heartbreak and the challenges of young adulthood, she must also cope with the voice in her head commenting on everything she does.' FROM games WHERE igdb_id = 387356 ON CONFLICT (game_id, language_code) DO NOTHING;
