INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gears of War: E-Day', 'Experience the brutal horror of Emergence Day through the eyes of Marcus Fenix in the origin story of one of gaming''s most acclaimed sagas.​ Fourteen years before Gears of War, war heroes Marcus Fenix and Dom Santiago return home to face a new nightmare: the Locust Horde. These subterranean monsters, grotesque and relentless, erupt from below, laying siege on humanity itself. ​ Built from the ground up with Unreal Engine 5, Gears of War: E-Day delivers unprecedented graphical fidelity.' FROM games WHERE igdb_id = 305160 ON CONFLICT (game_id, language_code) DO NOTHING;
