INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('track-star--1', 395754, '2026-09-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobts4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5lh1.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Track Star', 'Track Star is a text-based track and field career simulation. Set in high school, you build an athlete from scratch, choosing your event specialty and allocating stats across eight attributes. Over four seasons — Freshman through Senior — you train weekly, manage energy, compete in regular season meets, and chase qualification for Class, State, Regional, and National championships. Outside competition, a rivalry system tracks your history against recurring NPC opponents. A world events engine generates training flavor, program news, and breaking headlines that shift week to week. Achievements and milestone unlocks mark career progress. The game ends with an epilogue that reflects the full arc of your four years. Track Star is a single-player game built for players who want the grind of a career sim without the overhead of a management game.' FROM games WHERE igdb_id = 395754 ON CONFLICT (game_id, language_code) DO NOTHING;
