INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stupid Never Dies', 'Set in a monster-ruled otherworldly dungeon, Stupid Never Dies puts you in control of Davy, a timid zombie living at the very bottom of monster society. Defeat enemies, level up, and collect strange items to grow stronger on your quest to bring Julia, a frozen human girl, back to life. Steal enemy abilities, customize your undead body with bizarre upgrades, and experience fast-paced combat packed with innovation.' FROM games WHERE igdb_id = 381212 ON CONFLICT (game_id, language_code) DO NOTHING;
