INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('marvel-1943-rise-of-hydra--1', 216315, '2026-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa1rh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3st9.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marvel 1943: Rise of Hydra', 'This narrative-driven ensemble game stars Captain America Steve Rogers, Black Panther Azzuri (T''Challa''s grandfather), U.S. soldier and member of the Howling Commandos Gabriel Jones, and leader of the fledgling Wakandan Spy Network, Nanali. All four characters will be playable at different parts of the story. According to Skydance, players can look forward to "intuitive controls and exhilarating second-to-second gameplay that captures the action and excitement of Marvel, inspired by landmark comics, television, and films, as they navigate this all-new glob-trotting adventure."' FROM games WHERE igdb_id = 216315 ON CONFLICT (game_id, language_code) DO NOTHING;
