INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-bornless', 194855, '2026-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coar5s.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2gdb.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Bornless', 'The Bornless is an FPS action shooter packed with a variety of gameplay modes. Dive into last-man-standing co-op gameplay or try the thrilling demon versus disciple mode, all within a terror-filled world. Players pair up and form teams, conjure demons to aid in combat, and utilize strategic planning and resource management to survive. Whether you choose an aggressive playstyle or prefer a more cautious approach, the choice is yours. Join or create a Faction and amass various resources to upgrade and enhance your Safehouse or personalize your gear to give a new look to your arsenal as you go to war with other Factions. You will also experience deep lore and storyline involving all the characters within The Bornless universe, which will be revealed as facts are discovered by players.' FROM games WHERE igdb_id = 194855 ON CONFLICT (game_id, language_code) DO NOTHING;
