INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Five Laps at Freddy''s', 'Welcome to Five Laps at Freddy''s, The premier animatronic kart racing circuit featuring you favorite and lovable Fazbear friends! Sponsored by Fazbear Entertainment Select one of 12 of your favorite animatronic #FNaF characters and race on sixteen tracks set across 4 cups! Each track is based on your favorite locations from Five Nights at Freddy''s lore, including Fazbear Hills, Midnight Motorist and more!' FROM games WHERE igdb_id = 306217 ON CONFLICT (game_id, language_code) DO NOTHING;
