INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('solis--2', 354927, '2026-05-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa4lu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3uqw.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Solis', 'Solis is a hand-drawn adventure about technology and deception in a city at night. During a company trip you explore the city of Solis from dusk till dawn, talking with its inhabitants and meeting colleagues. This night you learn the painful truth about the company you work for. Will you remain loyal? In the game you explore an atmospheric and compact open world. Decisions within the game carry weight, influencing subsequent events, while the in-game text adjusts to reflect your choices. In Solis you explore the city, investigate your surroundings and talk with the inhabitants and colleagues you meet. Decisions within the game carry weight, influencing subsequent events, while the in-game text dynamically adjusts to reflect your choices. Interactions are streamlined to utilize a single button, aided by context-sensitive interaction icons. The GUI is a sparse as possible. Solis offers multiple endings and is crafted to be concise and compact. The complete game is estimated to run for approximately 2,5 hours.' FROM games WHERE igdb_id = 354927 ON CONFLICT (game_id, language_code) DO NOTHING;
