INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dread Neighbor', '"Dread Neighbor" is a 3D first-person horror game. You are a young woman who moves into a cheap, new apartment to save money. But something is wrong. From the closets, under the bed, through the cracks in the walls—you are being watched. Every corner feels alive with an unseen presence.' FROM games WHERE igdb_id = 382463 ON CONFLICT (game_id, language_code) DO NOTHING;
