INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tenebris Somnia', 'Tenebris Somnia is a horror adventure in the same vein as survival horror classics like Silent Hill or Resident Evil, but transferred to a retro 2D environment more typical of the N.E.S. or Famicom. You will struggle to survive by solving puzzles and fighting horrible creatures. The secret ingredient of the game is its cinematics. When you reach certain key points you will see sequences with a completely different aesthetic, made in live action with real actors and created by a professional film crew.' FROM games WHERE igdb_id = 216692 ON CONFLICT (game_id, language_code) DO NOTHING;
