INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kyoto Xanadu: The Blooming Phantom', 'Set in an alternate reality where Kyoto is the capital of Japan, Kyoto Xanadu players take on monsters and mysteries coming from the great labyrinth known as Xanadu. As a student, players will challenge the labyrinth and grow through their battles within Xanadu while also deepening bonds with various people during your daily life. Uncover the truth hidden both in the labyrinth and Kyoto itself.' FROM games WHERE igdb_id = 388439 ON CONFLICT (game_id, language_code) DO NOTHING;
