INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lifted', 'Step into the Anytime Elevator and get LIFTED — a cinematic single-player 2.5D puzzle-platform adventure from a former Disney ride designer. Slacker Ari Buktu only pokes his head into Professor Raventhorpe’s lab for extra credit; seconds later he’s hurtling through history on a reckless mission to steal a legendary tiara and fix the professor’s love-life. Each stop opens a new era, a bigger puzzle, and the shadow of a rival tomb-raider who’s always one jump behind…' FROM games WHERE igdb_id = 309518 ON CONFLICT (game_id, language_code) DO NOTHING;
