INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Machine Mind', 'What to do if your consciousness is trapped in a metal shell, and all around you is a post-apocalyptic world inhabited by enemies? There is only one task left - to survive at any cost! Machine Mind is an action game with survival and RTS elements, where you will have to build your own transportation, manage resources, build bases and blow up crazy raiders! Collect crafts, explore locations and fight to escape and discover all the secrets of this ruined world' FROM games WHERE igdb_id = 328621 ON CONFLICT (game_id, language_code) DO NOTHING;
