INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('greedfall-the-dying-world', 201961, '2026-03-10', 71, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobf3r.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar58kg.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'GreedFall: The Dying World', 'The story starts three years before the events of the first game and the adventures of De Sardet. This time you play as a native of Teer Fradee, uprooted by force from your island and taken to the continent of Gacane, where the colonists are from. In this old world ravaged by war and scarred by the Malichor plague and the political scheming of the different factions, you need to regain your freedom and control of your own destiny. Using diplomacy, cunning or combat, as well as help from allies you make, it''s up to you to end one man''s ambitions of conquest, which could spell the end for the continent and your island. Experience the unique world of GreedFall again by exploring the old continent! Travel across new landscapes, from Olima – the city of stars of the Bridge Alliance – to the shores of Uxantis, and uncover the secrets of these ancient lands. Meet all the factions that share control over these nations and navigate the treacherous waters of their schemes and conspiracies. Create your own character and find allies to join your team. Help them with their quests, uncover their secrets and make them your friends, rivals or even lovers. As well as equipping them the way you want, you can also take control of them in combat. Immerse yourself in an ever deeper RPG experience where every choice has an impact on your adventure and where diplomacy, manipulation, infiltration and combat are all viable paths for you to achieve your aims.' FROM games WHERE igdb_id = 201961 ON CONFLICT (game_id, language_code) DO NOTHING;
