INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wraith Ops', 'Wraith Ops is a fast-paced FPS shooter focusing on satisfying gunplay and back-to-basics playstyle. Its main goal is to bring together objective-based gameplay with a focus on teamwork, fast movement, snappy combat and more realistic/tactical features loved by many. Learning from its peers, we believe that realistic features and gameplay elements can work not only by putting obstacles in your way but by helping you overcome them, enhance the experience and improve your immersion.' FROM games WHERE igdb_id = 165574 ON CONFLICT (game_id, language_code) DO NOTHING;
