INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bellum', 372154, '2026-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coan5y.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4efz.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bellum', 'Bellum is the next evolution of platoon-scale tactical shooters, built in Unreal Engine 5 and shaped by die-hard fans who demanded more from the genre. Set in a fractured Africa of the 2030s, players are thrust into counter-insurgency campaigns where global powers engage in proxy wars across dense jungles, open savannas, and broken urban sprawl. Our unique limited-life system captures the tension of immersive milsim operations while keeping every match accessible, focused, and intense.' FROM games WHERE igdb_id = 372154 ON CONFLICT (game_id, language_code) DO NOTHING;
