INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'HyperCore: Rhythm Bullet Hell', 'HyperCore is a “Rhythm Bullet Hell”, mixing the frenetic action of classic bullet hell Shoot''em Up with semi-procedurally generated encounters based on the music. As PRISS, survive the action-packed levels in sync with the music and protect what is left of Humanity.' FROM games WHERE igdb_id = 122388 ON CONFLICT (game_id, language_code) DO NOTHING;
