INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('treeplanter', 354880, '2026-03-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa4jq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3uog.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Treeplanter', 'Create and enjoy a peaceful, interactive woodland throughout the changing seasons. For every copy sold, we plant a real tree!  Welcome to Treeplanter, an interactive woodland that grows and changes with the seasons. Piece together a small grove of trees, branch by branch, and watch as their roots blossom under the soil! As time goes by, an ecosystem of animals, plants and birds will move in, turning your creation into a living world. Changing seasons and weather will affect the miniature universe of your grove. Build your grove in a variety of landscapes, from sunny meadows to ancient ruins. Combining meditation and education, Treeplanter aims to teach players about the interconnected wonders of the natural world, above and below ground. Each copy of the game sold helps Henry plant trees, wildflowers, meadows and community orchards, through partnerships with schools, farms, communities and woodland charities. Meaning you’ll help restore real-life nature too!!' FROM games WHERE igdb_id = 354880 ON CONFLICT (game_id, language_code) DO NOTHING;
