INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Postal 2 Redux', 'A ground‑up overhaul of 2003’s infamous open‑world shooter. Part modernization, part love‑letter, POSTAL 2 Redux will hoist every original asset out of the creaking Unreal 1.5 engine and slam it into today’s Unity—delivering the same familiar week in the POSTAL Dude’s life with a merciless glow‑up and a bucket of new toys.' FROM games WHERE igdb_id = 349433 ON CONFLICT (game_id, language_code) DO NOTHING;
