INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Go Phish', 'Go Fish or go homeless. In this rogue-ish debt-builder, pay your rent by phishing a target in a supercharged version of the classic card game. Crack your victims password in a dynamic dialogue system, then use your loadout of unlockable suits and items to hack their PC and drain their savings.' FROM games WHERE igdb_id = 380970 ON CONFLICT (game_id, language_code) DO NOTHING;
