INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Evil Inside VR', 'Evil Inside VR is not just a simple adaptation to Virtual Reality. It’s a complete reimagining of the original story, rebuilt to deliver a new, deeper, and more terrifying psychological horror experience. With significant changes in gameplay, lighting, sound, and puzzle design, this version completely transforms the way you experience Mark’s nightmare. This is not the same Evil Inside you remember. It’s a new nightmare.' FROM games WHERE igdb_id = 366599 ON CONFLICT (game_id, language_code) DO NOTHING;
