INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deserter', 'In this stealth RPG, you play as a deserter who is forced to become a thief in a grim, war-torn town. You''ll have access to a rich arsenal of tools and devices: from lock picks and crowbars to grappling hooks and dynamite. Additionally, take advantage of your surroundings: find or create alternate routes, stick to the shadows, stay quiet, or use loud noises to cause distraction.' FROM games WHERE igdb_id = 323940 ON CONFLICT (game_id, language_code) DO NOTHING;
