INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ashen Vow', 'You are a knight sworn to God’s word, wielding only a sword against the darkness. But not all believers walk in good faith. The Black Maw has sunk its claws into the misguided, twisting their devotion into madness. Explore a once familiar castle now warped by evil, and cut down the corrupted horde' FROM games WHERE igdb_id = 373852 ON CONFLICT (game_id, language_code) DO NOTHING;
