INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alyssa', 'ALYSSA is an adventure horror game, in which you play as a little girl who wakes up in an unfamiliar place… Or rather, she’s awakened by Emily, who has a… strange mask permanently attached to her head. Armed with nothing but a small lighter, Alyssa must attempt to escape from this cursed place. Meanwhile, her tormentors lurk in the shadows, waiting for a single wrong move…' FROM games WHERE igdb_id = 271659 ON CONFLICT (game_id, language_code) DO NOTHING;
