INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('red-rust-pioneers', 349941, '2026-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9ztb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3qxj.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Red Rust Pioneers', 'Your story begins stranded in the unforgiving wilderness of the Wild West. Your one goal: to survive. Endure scorching days and freezing nights as you battle hunger, thirst, and the elements. Forage for food, hunt wildlife, and fish to stay alive. Scavenge the land to gather vital resources and craft the tools and weapons you’ll need to stand a chance in this brutal but breathtaking frontier. Can you master the elements and withstand blistering heat, violent rainstorms and freezing cold winters? Should you beat the odds and live, alone or with up to three friends, you’ll find yourself in a gorgeous, rugged, vibrant land. Will you be able to not only survive, but thrive? Build and grow your camp your way with easy to use base building mechanics. Fish in the lakes and rivers, or hunt in the atmospheric woodlands and open prairies. Farm and harvest a variety of crops to establish a self-sufficient camp. Adventure high into the mountains to mine resources, and craft better weapons and tools. Explore a beautifully realized, open world, fictionalized Wild West frontier and become the first to discover the untamed wilderness of Red Rust Valley. If you can overcome the threat of extreme hunger, brutal weather conditions and lethal wildlife you may just live to appreciate it.' FROM games WHERE igdb_id = 349941 ON CONFLICT (game_id, language_code) DO NOTHING;
