INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LeMrosh in the Lazy Kingdom', 'LeMrosh in the Lazy Kingdom is a funny point-and-click adventure game set in a medieval kingdom where nothing is as it seems. What starts out as a simple quest quickly turns into a tangle of puzzles, strange items and quirky characters. Explore, combine, question - just don''t get more involved than necessary! Get ready for hours of fun, unexpected twists and turns... and a little love story.' FROM games WHERE igdb_id = 343635 ON CONFLICT (game_id, language_code) DO NOTHING;
