INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Resonance: A Plague Tale Legacy', 'Set 15 years before Requiem, play as Sophia, a fierce young plunderer, on the run and determined to uncover the secrets of her past. Dive into an original story blending combat, myth and fate with a brand new take in the universe of A Plague Tale. Sophia’s journey leads to the Minotaur'' Island, where she faces deadly trials, navigates treacherous trails, solves puzzles, all while fighting and staying one step ahead of the army chasing her. But the true challenge awaits, as the terrifying creature hidden behind the myth will soon resonate with her…' FROM games WHERE igdb_id = 348168 ON CONFLICT (game_id, language_code) DO NOTHING;
