INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('super-meat-boy-3d', 348175, '2026-03-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9y1x.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3p1n.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Meat Boy 3D', 'Super Meat Boy 3D is a tough as nails platformer where you play as an animated cube of meat who''s trying to save his girlfriend (who happens to be made of bandages) from an evil fetus in a jar wearing a tux – IN 3D! Our meaty hero will leap from walls, over seas of buzz saws, through crumbling caves and pools of old trash sacrificing his own well-being to save his damsel in distress – IN 3D. Super Meat Boy 3D brings the old school difficulty of classic retro titles we all know and love and streamlines them down to the essential no bull straight forward twitch reflex platforming. Ramping up in difficulty from hard to soul crushing Meat Boy will brave lush (but also on fire) forests, vast dumps filled with the waste of mankind, and high-tech forges producing the very traps that will inevitably kill Meat Boy over and over and over - IN 3D! And if a bunch of levels weren''t enough, we also have epic boss fights and tons of unlockable secrets – IN 3D!' FROM games WHERE igdb_id = 348175 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 348175 AND ge.slug = 'platform' ON CONFLICT DO NOTHING;
