INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('orcs-must-die-by-the-blade', 377658, '2026-01-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaucc.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Orcs Must Die! By the Blade', 'The orcs are back—louder, dumber, and smellier than ever. And this time… they’re in your face. Literally! Orcs Must Die: By The Blade brings the legendary trap-slaughter franchise into fully immersive VR. Become a War Mage and defend Stormwreck Island in an all-new story as rotten rifts unleash corrupted orcs. Swing swords, trigger trinkets, punch orcs in the snout, and set ingenious trap chains that rocket screaming orcs across the room, pop off limbs, and spray gooey carnage everywhere. Explore epic fortresses, channel powerful magic, and experience the most up-close (and up-nose) orc-smashing action ever. Fight solo or team up in 2-player co-op to build traps, heal rifts, and doom the greenskin hordes with style. Mix brutal melee with comedic chaos. Build deadly defenses. Become a legend. Stormwreck Island won’t save itself… and the orcs aren’t going to punch themselves… Well, some might—but you should help!' FROM games WHERE igdb_id = 377658 ON CONFLICT (game_id, language_code) DO NOTHING;
