INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Saros', 'Beneath the shadow of an ominous eclipse, Arjun Devraj (Rahul Kohli) is a Soltari enforcer who will stop at nothing to pursue answers on the shape-shifting Carcosa, a world of dark secrets and hostile inhabitants. This planet is home to the corrupting influence of the Eclipse – a sinister force that awakens pure madness in everyone and everything. Throughout the surface of this troubled world, nothing remains untouched; it reaches every crevice of every biome.' FROM games WHERE igdb_id = 331215 ON CONFLICT (game_id, language_code) DO NOTHING;
