INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Retrospection of Tomorrow', 'In this non-linear, time-travel romance visual novel, you''ll date four captivating love interests just like in any ordinary otome game… until they die before your eyes(!). Trapped between memories and delusions, fighting fate itself—can you rewrite their endings? Dear time traveler, welcome home.' FROM games WHERE igdb_id = 354750 ON CONFLICT (game_id, language_code) DO NOTHING;
