INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cucina Stellata: Starred Cuisine', 'Gastronomy meets horror in an unsettling narrative experience set in 19th-century Romagna, Italy. Step into the shoes of a solitary writer and gourmet, inspired by the historical figure of Pellegrino Artusi, as a midnight snack spirals into the unexpected. Cucina Stellata ✦ Starred Cuisine isn''t your typical horror game: no frantic chases or cheap jump scares, but rather a thick atmosphere of tension, disturbing themes, and chilling twists that will linger in your mind long after the credits roll.' FROM games WHERE igdb_id = 341891 ON CONFLICT (game_id, language_code) DO NOTHING;
