INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Agecraft', 'Agecraft is a historical strategy and city-building game where players guide a civilization from the Stone Age to the space age. The game combines settlement building, resource management, and technological progression. Players construct cities, manage the economy, provide for their people, and expand across different eras, unlocking new buildings, production chains, and methods of transportation as history advances.' FROM games WHERE igdb_id = 362933 ON CONFLICT (game_id, language_code) DO NOTHING;
