INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Woodo', 'Woodo is a 3D puzzle game. The player immerses in a calm and peaceful world where time stopped at the happy moment. With imaginary friend Woodo, player build bit by bit this tiny world. Woodo tells the player stories and makes the player feel not lonely while playing. The game looks like a wooden kit from childhood.' FROM games WHERE igdb_id = 145078 ON CONFLICT (game_id, language_code) DO NOTHING;
