INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hirotonfa''s American Revolution Smuggler', 'A historical trading and dating sim set during the American Revolution. Manage a trade ship hauling goods between colonial ports, profit from volatile daily market swings, and navigate faction dangers, from militias to pirates, while choosing sides that affect regional quests. Along the way, romance charming colonial “state-chans” across territories like Louisiana and Quebec, blending economic strategy, risk-filled navigation, and character-driven narrative.' FROM games WHERE igdb_id = 366565 ON CONFLICT (game_id, language_code) DO NOTHING;
