INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Norse: Oath of Blood', 'Norse is a turn-based tactics and combat game for PC and console. Set against the rich backdrop of the Viking Age, join Gunnar, a young warrior, on a relentless quest for revenge across the rugged landscapes of Norway. Build a thriving settlement, govern your community, forge alliances, grow strong, and win the favour of the gods. For this is a time when legends are forged in the fires of conflict, and only the brave are remembered. Written by prize-winning and Sunday Times bestselling author Giles Kristian, Norse is set in a fully realised historical world, driven by a compelling narrative and brimming with memorable characters.' FROM games WHERE igdb_id = 336868 ON CONFLICT (game_id, language_code) DO NOTHING;
