INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nitro Turtles', 'Nitro Turtles is a racing game about super fast turtles! Reach insane speeds with awesome shell-attached gadgets, compete in crazy races with friends, and sprint across the finish line to claim ultimate turtle victory! To be the fastest turtle around, you''ll need to master shell gadget usage, learn every shortcut imaginable, and maybe even consider using performance-enhancing seaweed!' FROM games WHERE igdb_id = 371518 ON CONFLICT (game_id, language_code) DO NOTHING;
