INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Saint of Chains', 'Psychological single-player first-person horror. Explore dark environments, fight with melee and guns, and solve puzzles in this retro 2000s-inspired nightmare where the truth is more terrifying than the monsters. Retro Horror - Reborn: A love letter to Silent Hill 3, Lost in Vivo, Condemned: Criminal Origins, and Cry of Fear. Built in the haunting visual style of the PS2 / Xbox360 era — when every shadow felt alive, and every step sounded like a confession.' FROM games WHERE igdb_id = 374295 ON CONFLICT (game_id, language_code) DO NOTHING;
