INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lustra: Lachea’s Tale', 'LUSTRA: Lachea’s Tale is a story-rich RPG that combines real-time spellcasting, exploration, and settlement building, set in a fractured floating island realm where ancient magic and mystery intertwine. Play as Lachea, a young mage shaped by the world around her, learning to lead, grow, and take control of her path in a land suspended between ruin and renewal. Lustra invites players to see the world through multiple perspectives, to reflect on morality, empathy, and responsibility, and to shape not just the outcome of a magical world, but the kind of person Lachea becomes along the way.' FROM games WHERE igdb_id = 346790 ON CONFLICT (game_id, language_code) DO NOTHING;
