INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('lost-host', 378896, '2026-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob3bs.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4qht.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lost Host', 'Lost Host is a story-driven adventure puzzle game about a small toy car searching for its missing owner. When the boy mysteriously disappears, the toy car begins a journey through the house and beyond, exploring dark rooms, hallways, foggy streets, and abandoned places while following clues to uncover what happened. Players control the toy car as it navigates dangerous environments, solves physics-based puzzles, and interacts with objects to progress. The world is full of hazards for a tiny toy car - heights, fire, water - as well as enemies such as dogs, robotic vacuums, and hostile toy creatures. The game combines atmospheric exploration, light horror elements, and emotional storytelling, creating a family-friendly adventure centered on mystery, discovery, and survival in a large, human-sized world.' FROM games WHERE igdb_id = 378896 ON CONFLICT (game_id, language_code) DO NOTHING;
