INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Humanity Echo: Cyberpunk Tactical RPG', 'Humanity Echo is a tactical turn-based RPG set in the rusted harbour slums of Odesa, 2044. You play as an Engineer - not a soldier - using sabotage, environmental manipulation, and raw intellect to outsmart a corporate machine. In this high-tech, low-life world, every explosion carries physical weight and every shot leaves a unique acoustic imprint.' FROM games WHERE igdb_id = 381059 ON CONFLICT (game_id, language_code) DO NOTHING;
