INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pathologic 3', 'Save a town from a mysterious plague in this in narrative first-person RPG. Learn the stories of its unusual inhabitants. Shape their lives with your decrees. Diagnose patients. Face the Plague. Connect the dots. Find out who killed the immortal man. Correct your mistakes in the past.' FROM games WHERE igdb_id = 319087 ON CONFLICT (game_id, language_code) DO NOTHING;
