INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Homura Hime', '"Homura Hime" is a third person action game, featuring Japanese anime visuals and intense 3D bullet curtain gameplay. Alongside Homurahime, fight against Demon Girls possessed by deviant "emotions", and get closer to discovering the truth of not only the fallen, but also your own veiled legacy.' FROM games WHERE igdb_id = 199055 ON CONFLICT (game_id, language_code) DO NOTHING;
