INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Code Vein II', 'Code Vein II is an action role-playing game set in a post-apocalyptic world where Revenants are being transformed into hostile "Horrors." A Revenant Hunter must partner with a time-manipulating companion named Lou. Gameplay features third-person action combat and deep RPG progression, emphasizing specialized Blood-based mechanics and character customization. An evolved Partner System enhances tactical cooperation with AI companions during exploration and high-difficulty boss encounters. Success depends on mastering diverse weaponry and temporal abilities to survive a world defined by memory and ruin.' FROM games WHERE igdb_id = 347636 ON CONFLICT (game_id, language_code) DO NOTHING;
