INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Halo: Campaign Evolved', 'Experience Where the Legend Begins Halo: Campaign Evolved is a faithful yet modernized remake of Halo: Combat Evolved’s campaign. Experience the original story rebuilt with high-definition visuals, updated cinematics, and refined controls, plus three brand-new prequel missions featuring the Master Chief and Sgt. Johnson. A broader arsenal of weapons, vehicles, enemies, and gameplay-modifying “Skulls” – optional modifiers that change combat in fun and challenging ways – add fresh tactics and endless replayability.' FROM games WHERE igdb_id = 375232 ON CONFLICT (game_id, language_code) DO NOTHING;
