INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Project Homecoming Haven', 'Play as a Trauma Cleaner; a housecleaning service that receives requests from bereaving families to clean up rooms and houses left by the deceased. In your job, you will learn about those who left the world of their own volition or others. Learn about the life they lived, choose belongings of the deceased to be given to their families, or keep them for yourself to grow your Trauma Cleaning business.' FROM games WHERE igdb_id = 300711 ON CONFLICT (game_id, language_code) DO NOTHING;
