INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '[Herror] Gas Station Case', '[HERROR] is a series of short horror episodes where everyday work routines collide with paranormal threats. Each episode is a unique standalone story lasting 1.5–2 hours. Dan Cooper, a 25-year-old night shift gas station worker in Ohio, recently laid off from a uranium plant, is trying to put his life back together. But everything changes when his friend Michael discovers a mysterious case by the lake. Soon, people begin to vanish in the surrounding woods, and the cozy gas station turns into a deadly trap.' FROM games WHERE igdb_id = 369486 ON CONFLICT (game_id, language_code) DO NOTHING;
