INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '500 Caliber Contractz', '500 Caliber Contractz is a momentum-based 3D-Platformer in which you play as a contract killer hired via crowdfunding to murder CEOs, Disgraced Sinister Ex-Doctors, Private-Prison-Owning DJs, etc. With your handy high caliber sniper rifle and a chest full of anxiety, you can and will propel yourself to where you need to be. Collect tokens that float around for a reason I haven''t bothered coming up with and then murder your target. Do it. Please.' FROM games WHERE igdb_id = 268103 ON CONFLICT (game_id, language_code) DO NOTHING;
