INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Legends of Castile', 'Legends of Castile is a comic fantasy point-and-click adventure set in the historic Castile region of Spain in the 19th century. It tells the story of a village girl who must investigate the myths and legends of Castile to fulfill her dream of becoming a nun. Advance the story by solving puzzles and riddles, meeting all kinds of characters, defeating fantastic creatures with your wit, and exploring places all around Castile.' FROM games WHERE igdb_id = 240636 ON CONFLICT (game_id, language_code) DO NOTHING;
